  ('cbf25d85-7b49-5074-b896-90264c5b423c', '22222222-2222-2222-2222-222222222212', 'short', '已知𝑓(𝑥, 𝑦) = 𝑥2 −𝑦2 −𝑥+ 𝑦+ 1，则𝑓(𝑥, 𝑦) = 1', null, '', '', '数学/第2章 代数式  合订版.pdf', 22, true, 45, null),
